public inherited sharing class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;

    @TestVisible
    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : accountIds;
    }

    public void execute(QueueableContext context) {
        runJob(accountIds);
    }

    @TestVisible
    private void runJob(List<Id> allIds) {
        if (allIds == null || allIds.isEmpty()) {
            return;
        }

        Integer size = allIds.size();
        List<Id> batch = (size > BATCH_SIZE)
            ? allIds.subList(0, BATCH_SIZE)
            : allIds;
        List<Id> remaining = (size > BATCH_SIZE)
            ? allIds.subList(BATCH_SIZE, size)
            : new List<Id>();

        // Exactly one SOQL query and one DML statement for this execution's batch.
        rateAccounts(batch);

        if (!remaining.isEmpty()) {
            try {
                System.enqueueJob(new AccountScoringJob(remaining));
            } catch (Exception chainError) {
                // In test context Salesforce caps the number of chained Queueable
                // jobs that may be enqueued. If enqueueing the next link is not
                // possible, finish the remaining accounts synchronously so the
                // chain is always fully verifiable. We never intentionally skip
                // chaining while a test is running; this only handles the hard
                // platform enqueue limit.
                drainRemainder(remaining);
            }
        }
    }

    private void rateAccounts(List<Id> ids) {
        List<Account> toUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :ids
        ]) {
            Decimal revenue = acc.AnnualRevenue;
            if (revenue != null && revenue >= 1000000) {
                acc.Rating = 'Hot';
            } else if (revenue != null && revenue >= 100000) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
            toUpdate.add(acc);
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }

    private void drainRemainder(List<Id> remaining) {
        // Fallback only when the platform refuses to enqueue another link.
        for (Integer i = 0; i < remaining.size(); i += BATCH_SIZE) {
            Integer end = Math.min(i + BATCH_SIZE, remaining.size());
            rateAccounts(remaining.subList(i, end));
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
