public with sharing class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {}

    public void execute(SchedulableContext ctx) {
        purgeLogs();
    }

    @TestVisible
    private static void purgeLogs() {
        Datetime standardCutoff = System.now().addDays(-30);
        Datetime errorCutoff = System.now().addDays(-180);

        List<FB_Integration_Log__c> toDelete = new List<FB_Integration_Log__c>();

        for (List<FB_Integration_Log__c> scope : [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < :standardCutoff
                       AND (Level__c = null OR Level__c != 'ERROR'))
                   OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')]) {
            toDelete.addAll(scope);
        }

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
    }

    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }
}
