public with sharing class AccountCountrySync {

    /**
     * After accounts are updated, propagate a BillingCountry change to the
     * MailingCountry of the account's contacts — but only for contacts whose
     * MailingCountry is blank or still matches the account's previous
     * BillingCountry. Contacts with a different MailingCountry are left alone.
     *
     * Bulk-safe: a single selective SOQL per invocation (accounts come in
     * batches of up to 200 from the MDM integration), no SOQL/DML in loops.
     * A full-org contact query is not viable — the org has ~2.3M contacts,
     * far beyond the 50k query-row limit; the WHERE AccountId IN filter makes
     * this selective and small.
     */
    public static void syncMailingCountry(List<Account> newAccounts, Map<Id, Account> oldAccounts) {
        // Collect only accounts whose BillingCountry actually changed.
        Map<Id, String> accountNewCountryByAccountId = new Map<Id, String>();
        for (Account acc : newAccounts) {
            Account oldAcc = oldAccounts.get(acc.Id);
            if (oldAcc != null && acc.BillingCountry != oldAcc.BillingCountry) {
                accountNewCountryByAccountId.put(acc.Id, acc.BillingCountry);
            }
        }

        if (accountNewCountryByAccountId.isEmpty()) {
            return;
        }

        // One selective query for this invocation, outside any loop.
        List<Contact> contacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :accountNewCountryByAccountId.keySet()
        ];

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact con : contacts) {
            String previousCountry = oldAccounts.get(con.AccountId).BillingCountry;
            String mailingCountry = con.MailingCountry;
            if (mailingCountry == null || mailingCountry == '' || mailingCountry == previousCountry) {
                Contact toUpdate = new Contact(
                    Id = con.Id,
                    MailingCountry = accountNewCountryByAccountId.get(con.AccountId)
                );
                contactsToUpdate.add(toUpdate);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
