import { LightningElement, api } from 'lwc';

let instanceCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];
    _value = '';
    activeIndex = 0;
    uid = `status-listbox-${++instanceCounter}`;

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue;
        this.syncActiveWithValue();
    }

    get selectedOption() {
        return this.options.find((option) => option.value === this._value);
    }

    get activeId() {
        const activeOption = this.options[this.activeIndex];
        if (!activeOption) {
            return undefined;
        }
        return this.optionId(activeOption.value);
    }

    optionId(value) {
        return `${this.uid}-option-${value}`;
    }

    syncActiveWithValue() {
        const index = this.options.findIndex(
            (option) => option.value === this._value
        );
        if (index >= 0) {
            this.activeIndex = index;
        } else {
            this.activeIndex = 0;
        }
    }

    renderedCallback() {
        // Ensure the active option is in sync if options were set/changed by the parent.
        if (
            this.activeIndex >= this.options.length &&
            this.options.length > 0
        ) {
            this.syncActiveWithValue();
        }
    }

    handleKeyDown(event) {
        const keys = [
            'ArrowDown',
            'ArrowUp',
            'Home',
            'End',
            'Enter',
            ' ',
        ];
        if (!keys.includes(event.key)) {
            return;
        }
        event.preventDefault();

        const maxIndex = this.options.length - 1;
        switch (event.key) {
            case 'ArrowDown':
                this.activeIndex = Math.min(this.activeIndex + 1, maxIndex);
                break;
            case 'ArrowUp':
                this.activeIndex = Math.max(this.activeIndex - 1, 0);
                break;
            case 'Home':
                this.activeIndex = 0;
                break;
            case 'End':
                this.activeIndex = maxIndex;
                break;
            case 'Enter':
            case ' ':
                this.selectIndex(this.activeIndex);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const target = event.currentTarget;
        const value = target.dataset.value;
        const index = this.options.findIndex(
            (option) => option.value === value
        );
        if (index < 0) {
            return;
        }
        this.activeIndex = index;
        this.selectIndex(index);
    }

    selectIndex(index) {
        const option = this.options[index];
        if (!option) {
            return;
        }
        if (option.value === this._value) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value },
            })
        );
    }
}
