public with sharing class FamilyService {

    /**
     * Links parents to children in NPSP.
     *
     * For each (child -> parent) pair, inserts a single npe4__Relationship__c
     * of type 'Parent' (status 'Current') from the child to the parent.
     * NPSP's own Relationship trigger (reciprocal method: List Setting) then
     * creates the single reciprocal record (Son / Daughter / Child, per the
     * Parent row of the npe4__Relationship_Lookup__c setting), so each pair
     * ends up with exactly one relationship record in each direction.
     *
     * Safe to re-run: any pair that already has a relationship record in
     * either direction is skipped. Duplicate pairs within the same input map
     * are also skipped.
     *
     * Limits: at most 1 SOQL query and 1 DML statement.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null or empty input does nothing.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect every contact involved so a single query can find any
        // existing relationship (in either direction) between the pairs.
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            contactIds.add(childId);
            contactIds.add(parentIdByChildId.get(childId));
        }

        // One SOQL query: fetch existing relationships among the involved
        // contacts and index them in both directions for fast lookups.
        Map<String, Id> existingByPairKey = new Map<String, Id>();
        for (npe4__Relationship__c rel : [
                SELECT npe4__Contact__c, npe4__RelatedContact__c
                FROM npe4__Relationship__c
                WHERE npe4__Contact__c IN :contactIds
                  AND npe4__RelatedContact__c IN :contactIds
        ]) {
            String forwardKey = rel.npe4__Contact__c + '-' + rel.npe4__RelatedContact__c;
            String reverseKey = rel.npe4__RelatedContact__c + '-' + rel.npe4__Contact__c;
            existingByPairKey.put(forwardKey, rel.Id);
            existingByPairKey.put(reverseKey, rel.Id);
        }

        List<npe4__Relationship__c> newRelationships =
                new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            // Skip invalid pairs (missing parent, self-relationship).
            if (parentId == null || childId == parentId) {
                continue;
            }

            // Skip if any relationship already exists between the two
            // contacts, in either direction.
            String forwardKey = childId + '-' + parentId;
            if (existingByPairKey.containsKey(forwardKey)) {
                continue;
            }

            // Mark both directions so duplicate pairs in the same input
            // (including reversed pairs) are only processed once.
            existingByPairKey.put(forwardKey, null);
            existingByPairKey.put(parentId + '-' + childId, null);

            newRelationships.add(new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = 'Parent',
                    npe4__Status__c = 'Current'
            ));
        }

        // Single DML statement. The NPSP Relationship trigger creates the
        // reciprocal records (Son / Daughter / Child) automatically.
        if (!newRelationships.isEmpty()) {
            insert newRelationships;
        }
    }
}
