/**
 * TAF action: creates an onboarding Task for the owner of each newly created
 * Account of Type 'Customer - Direct' or 'Customer - Channel'.
 * Runs only in the after insert context; one DML statement per execution,
 * skipped entirely when no account qualifies.
 */
public inherited sharing class TA_Account_CreateOnboardingTask
        implements TriggerAction.AfterInsert {

    private static final Set<String> ONBOARDING_TYPES = new Set<String>{
        'Customer - Direct', 'Customer - Channel'
    };

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> tasks = new List<Task>();
        Date dueDate = Date.today().addDays(7);
        for (SObject sObj : triggerNew) {
            Account account = (Account) sObj;
            if (ONBOARDING_TYPES.contains(account.Type)) {
                tasks.add(new Task(
                    Subject = 'Onboard new customer',
                    WhatId = account.Id,
                    OwnerId = account.OwnerId,
                    ActivityDate = dueDate,
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }
        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
